{
    "API_calls": [],
    "collected_information": {
        "Environment_Setup": {
            "Prerequisites": [
                "Docker Desktop must be open and running.",
                "Node.js version `v24` (can use `nvm` with `.nvmrc` file)."
            ],
            "Docker_Setup": {
                "Build_Docker_Image": "docker build --tag cyberchef --ulimit nofile=10000 .",
                "Run_Docker_Container": "docker run -it -p 8080:8080 cyberchef",
                "Run_Pre_Built_Image": "docker run -it -p 8080:8080 ghcr.io/gchq/cyberchef:latest",
                "Browser_URL": "http://localhost:8080"
            },
            "From_Source": {
                "Commands": [
                    "git clone https://github.com/gchq/CyberChef.git",
                    "cd CyberChef",
                    "npm install"
                ],
                "Optional": "Use `nvm` for managing Node.js version (refer to `.nvmrc` file)."
            }
        },
        "Test_Execution": {
            "Testing_Framework": "Node.js test suites + browser-based UI tests",
            "Test_Commands": {
                "Run_Tests": "npm test",
                "Run_UI_Tests": "npm run testui",
                "Linting": "npm run lint",
                "Node_Heap_Adjustment": "npm run setheapsize"
            }
        },
        "Dependencies_and_Scripts": {
            "Dependencies": [
                "@alexaltea/capstone-js: ^3.0.5",
                "@astronautlabs/amf: ^0.0.6",
                "@blu3r4y/lzma: ^2.3.3",
                "@noble/hashes: 2.4.0",
                "Multiple other dependencies listed"
            ],
            "DevDependencies": [
                "@babel/eslint-parser: ^8.0.6",
                "@babel/plugin-transform-runtime: ^8.0.6",
                "Numerous other dev dependencies listed"
            ],
            "Scripts": {
                "Start_Application": "npx grunt dev",
                "Build_Production": "npx grunt prod",
                "Run_Node_Tests": "npx grunt configTests && node --no-warnings --no-deprecation --openssl-legacy-provider tests/node/index.mjs && node --no-warnings --no-deprecation --openssl-legacy-provider --trace-uncaught tests/operations/index.mjs",
                "Run_UI_Tests": "npx grunt testui",
                "Run_UI_Tests_DevMode": "npx nightwatch --env=dev",
                "Lint_Code": "npx grunt lint",
                "Set_Node_Heap_Size": "export NODE_OPTIONS=--max_old_space_size=2048"
            }
        },
        "Node_Version": "24"
    },
    "terminate": true
}
